    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // VAT = base × 21 / 100, rounded with banker's rounding
  const expectedVat = roundCents(result[0].base * 0.21);
  assert.equal(result[0].vat, expectedVat);
});

