  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const fee1 = lateFee(issued1, '2025-03-18');
  const fee2 = lateFee(issued2, '2025-03-18');

  // fee2 should be roughly double fee1 (proportional to amount)
  assert.equal(fee2, fee1 * 2);
});
